import{_ as c,I as s,o as x,c as f,j as a,a as l,J as n,b6 as e}from"./chunks/framework.COUcLbTA.js";const A=JSON.parse('{"title":"大语言模型的工作原理","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/llm-principles.md","filePath":"zh-cn/appendix/8-artificial-intelligence/llm-principles.md"}'),y={name:"zh-cn/appendix/8-artificial-intelligence/llm-principles.md"};function _(u,t,b,T,E,P){const i=s("LlmQuickStartDemo"),r=s("TokenizationDemo"),o=s("EmbeddingDemo"),g=s("TokenizerToMatrix"),p=s("RNNvsTransformer"),d=s("TrainingInferenceDemo"),h=s("ThinkingModelDemo"),k=s("MoEDemo"),m=s("LinearAttentionDemo");return x(),f("div",null,[t[0]||(t[0]=a("h1",{id:"大语言模型的工作原理",tabindex:"-1"},[l("大语言模型的工作原理 "),a("a",{class:"header-anchor",href:"#大语言模型的工作原理","aria-label":"Permalink to “大语言模型的工作原理”"},"​")],-1)),t[1]||(t[1]=a("blockquote",null,[a("p",null,[l("💡 "),a("strong",null,"学习指南"),l("：本章节无需编程基础，通过交互式演示带你深入了解大语言模型（LLM）的底层工作原理。我们将从最基础的分词讲起，一直到 GPT 是如何训练和推理的。")])],-1)),n(i),t[2]||(t[2]=e(`<h2 id="_0-引言-从人类语言到机器计算" tabindex="-1">0. 引言：从人类语言到机器计算 <a class="header-anchor" href="#_0-引言-从人类语言到机器计算" aria-label="Permalink to “0. 引言：从人类语言到机器计算”">​</a></h2><p>人类用语言交流，计算机用数字计算。 <strong>大语言模型 (LLM)</strong> 的本质，就是一座连接这两个世界的桥梁。</p><p>它的核心任务只有一个：<strong>把“理解语言”这个问题，转化成“数学计算”的问题。</strong></p><p>为了实现这个目标，我们需要解决三个核心挑战：</p><ol><li><strong>翻译</strong>：怎么把文字变成数字？（分词 &amp; Embedding）</li><li><strong>效率</strong>：怎么让计算机算得快？（矩阵运算）</li><li><strong>记忆</strong>：怎么让计算机读懂上下文？（Transformer 模型）</li></ol><p>本教程将带你从零开始，一步步拆解这座桥梁的构建过程。</p><hr><h2 id="_1-第一步-翻译-tokenization" tabindex="-1">1. 第一步：翻译 (Tokenization) <a class="header-anchor" href="#_1-第一步-翻译-tokenization" aria-label="Permalink to “1. 第一步：翻译 (Tokenization)”">​</a></h2><p>计算机看不懂“汉堡”这两个字，它只认识数字。 所以，我们的第一个任务是：<strong>把文本切分成计算机能理解的最小单位</strong>。</p><h3 id="_1-1-什么是分词" tabindex="-1">1.1 什么是分词？ <a class="header-anchor" href="#_1-1-什么是分词" aria-label="Permalink to “1.1 什么是分词？”">​</a></h3><p>分词就是把一整句拆成一个个“词单元”（Token）。</p><ul><li><strong>英文</strong>：自带空格，天然容易分词（如 <code>I love AI</code>）。</li><li><strong>中文</strong>：没有空格，需要算法来切分（如 <code>我爱人工智能</code>）。</li></ul><h4 id="tokenizer-翻译官" tabindex="-1">Tokenizer (翻译官) <a class="header-anchor" href="#tokenizer-翻译官" aria-label="Permalink to “Tokenizer (翻译官)”">​</a></h4><p>执行分词这个动作的程序，我们称之为 <strong>Tokenizer</strong>。 它就像是一个翻译官，负责将人类的文字翻译成机器能读懂的数字序列。</p><p>现代 LLM (如 GPT-4) 通常使用 <strong>Subword Tokenization (子词分词)</strong> 技术（如 BPE 算法）。 它的聪明之处在于：<strong>常用词保持完整，生僻词拆分</strong>。</p><p>以下是一个真实的 BPE 分词示例（基于 GPT-4 Tokenizer）：</p><p><strong>Input</strong>: <code>&quot;The quick brown fox jumps over the lazy dog. \\n今天天气真不错！&quot;</code></p><p><strong>Token List</strong>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>index=791,   string=&#39;The&#39; </span></span>
<span class="line"><span>index=4062,  string=&#39; quick&#39; </span></span>
<span class="line"><span>index=14198, string=&#39; brown&#39; </span></span>
<span class="line"><span>index=39935, string=&#39; fox&#39; </span></span>
<span class="line"><span>index=83368, string=&#39; jumps&#39;   &lt;-- 如果被拆分，可能会是 &#39; jump&#39; + &#39;s&#39;</span></span>
<span class="line"><span>index=927,   string=&#39; over&#39; </span></span>
<span class="line"><span>index=279,   string=&#39; the&#39; </span></span>
<span class="line"><span>index=16053, string=&#39; lazy&#39; </span></span>
<span class="line"><span>index=3290,  string=&#39; dog&#39; </span></span>
<span class="line"><span>index=13,    string=&#39;.&#39; </span></span>
<span class="line"><span>index=198,   string=&#39;\\n&#39;       &lt;-- 换行符 </span></span>
<span class="line"><span>index=33838, string=&#39;今天&#39;      &lt;-- 常用词直接合并 </span></span>
<span class="line"><span>index=54580, string=&#39;天气&#39; </span></span>
<span class="line"><span>index=20265, string=&#39;真&#39; </span></span>
<span class="line"><span>index=57672, string=&#39;不错&#39; </span></span>
<span class="line"><span>index=171,   string=&#39;！&#39;</span></span></code></pre></div><blockquote><p><strong>关于生僻字的处理</strong>： 如果遇到词表中不存在的生僻字（假设“今”字很生僻），模型会回退到 <strong>Byte 级别</strong> 进行编码。</p><ol><li>Raw Input: <code>今</code></li><li>Bytes: <code>\\xE4 \\xBB \\x8A</code></li><li>BPE 查找: 先找 <code>\\xE4\\xBB\\x8A</code> -&gt; 没找到 -&gt; 拆分为 <code>\\xE4\\xBB</code> (ID=1001) + <code>\\x8A</code> (ID=2002)。</li><li>最终 Token: <code>[1001, 2002]</code>。</li></ol><p>这种机制保证了<strong>无论输入什么字符，模型都能处理，永远不会出现 OOV (Out Of Vocabulary) 问题</strong>。</p></blockquote>`,20)),n(r),t[3]||(t[3]=e('<p><strong>关键点</strong>：LLM 处理的不是单词，而是 <strong>Token ID</strong>（一串数字索引）。</p><hr><h2 id="_2-核心难题-如何让计算机-计算-语言" tabindex="-1">2. 核心难题：如何让计算机“计算”语言？ <a class="header-anchor" href="#_2-核心难题-如何让计算机-计算-语言" aria-label="Permalink to “2. 核心难题：如何让计算机“计算”语言？”">​</a></h2><p>我们的任务是处理语言。但计算机只认识数字。 最直接的想法是：给每个词编个号（ID）。</p><ul><li>苹果 -&gt; ID 10</li><li>香蕉 -&gt; ID 20</li></ul><h3 id="_2-1-为什么不用简单的-id" tabindex="-1">2.1 为什么不用简单的 ID？ <a class="header-anchor" href="#_2-1-为什么不用简单的-id" aria-label="Permalink to “2.1 为什么不用简单的 ID？”">​</a></h3><p>如果只用 ID，计算机会认为“10”和“20”只是两个毫无关系的数字。 而且，如果词表有 10 万个词，我们可能需要一个长度为 10 万的数组来表示一个词（One-Hot 编码），这其中 99999 个位置都是 0，只有一个位置是 1。</p><ul><li><strong>缺点1：太浪费</strong>（稀疏，One-Hot 数组太大）。</li><li><strong>缺点2：没内涵</strong>（无法表示“苹果”和“香蕉”都是水果）。</li></ul><h3 id="_2-2-解决方案-embedding-稠密向量" tabindex="-1">2.2 解决方案：Embedding (稠密向量) <a class="header-anchor" href="#_2-2-解决方案-embedding-稠密向量" aria-label="Permalink to “2.2 解决方案：Embedding (稠密向量)”">​</a></h3><p>为了<strong>高效</strong>且<strong>有内涵</strong>地表达一个词，我们发明了 <strong>Embedding</strong>。 它不再用一个长长的 0/1 数组，而是用一个短一点的、填满小数的数组（比如 512 个数字）来描述一个词。</p><ul><li>比如：<code>[0.8 (是水果), 0.1 (红色), 0.9 (甜)...]</code> 这样，我们不仅压缩了数据，还把词义变成了可以计算的“坐标”。</li></ul>',11)),n(o),t[4]||(t[4]=e('<hr><h2 id="_3-从-单词-到-矩阵" tabindex="-1">3. 从 单词 到 矩阵 <a class="header-anchor" href="#_3-从-单词-到-矩阵" aria-label="Permalink to “3. 从 单词 到 矩阵”">​</a></h2><p>解决了“一个词”的表达问题，接下来要解决“一句话”的表达问题。</p><h3 id="_3-1-为什么要是矩阵" tabindex="-1">3.1 为什么要是矩阵？ <a class="header-anchor" href="#_3-1-为什么要是矩阵" aria-label="Permalink to “3.1 为什么要是矩阵？”">​</a></h3><p>因为一句话包含了很多个词。</p><ul><li>一个词 = 一行数字（向量）。</li><li>一句话 = 很多行数字堆叠在一起。 这就是<strong>矩阵</strong>。</li></ul><p>之所以要拼成矩阵，是因为现代计算机的核心硬件——<strong>GPU (显卡)</strong>，天生就是为了做矩阵运算而设计的。 只有把语言变成了矩阵，才能利用 GPU 的并行能力，实现<strong>高效</strong>的推理和训练。</p><h3 id="_3-2-完整流水线" tabindex="-1">3.2 完整流水线 <a class="header-anchor" href="#_3-2-完整流水线" aria-label="Permalink to “3.2 完整流水线”">​</a></h3><p>回顾一下数据是怎么流动的：</p><ol><li><strong>分词</strong>：把文本切碎。</li><li><strong>索引</strong>：把碎片变成 ID。</li><li><strong>Embedding</strong>：把 ID 变成向量（为了语义和压缩）。</li><li><strong>堆叠</strong>：把向量拼成矩阵（为了 GPU 高效计算）。</li></ol>',10)),n(g),t[5]||(t[5]=e('<hr><h2 id="_3-5-插播-到底什么是-模型" tabindex="-1">3.5 插播：到底什么是“模型”？ <a class="header-anchor" href="#_3-5-插播-到底什么是-模型" aria-label="Permalink to “3.5 插播：到底什么是“模型”？”">​</a></h2><p>在讲具体的架构之前，我们先通俗地理解一下“模型”这个词。</p><p>在 AI 领域，<strong>模型（Model）</strong> 其实就是一个超级复杂的<strong>函数</strong>或者<strong>黑盒子</strong>。</p><ul><li><strong>输入</strong>：一堆数字（比如上面的 Token ID）。</li><li><strong>处理</strong>：黑盒子里有亿万个参数（可以理解为亿万个调节旋钮），它们会对输入数据进行疯狂的加减乘除运算。</li><li><strong>输出</strong>：另一堆数字（代表预测结果，比如下一个词的概率）。</li></ul><p><strong>打个比方：</strong></p><p>你可以把模型想象成一位<strong>经验丰富的老厨师</strong>：</p><ol><li><strong>输入（食材）</strong>：你给他牛肉、土豆、番茄。</li><li><strong>模型（厨师的脑子）</strong>：他根据自己学过的成千上万道菜谱（训练数据），在脑子里快速计算：牛肉切块、土豆去皮、火候控制...</li><li><strong>输出（菜肴）</strong>：最后端出一盘土豆炖牛腩。</li></ol><p>所谓的<strong>训练（Training）</strong>，就是让这位厨师从学徒做起，让他试错亿万次。做咸了就调一下“盐旋钮”，做淡了就调一下“火候旋钮”，直到他能稳定做出美味的菜肴。</p><p>现在的 LLM，就是一位“读过全人类书本”的超级厨师，只不过他炒的不是菜，而是文字。</p><h2 id="_4-进化之路-从-rnn-到-transformer" tabindex="-1">4. 进化之路：从 RNN 到 Transformer <a class="header-anchor" href="#_4-进化之路-从-rnn-到-transformer" aria-label="Permalink to “4. 进化之路：从 RNN 到 Transformer”">​</a></h2><p>有了数据（Token），有了厨师（模型），接下来要看这位厨师是怎么思考的。</p><p>在 AI 进化史上，主要有两种“思考方式”（架构）：<strong>RNN</strong> 和 <strong>Transformer</strong>。</p><h3 id="_4-1-以前的笨办法-rnn-传话游戏" tabindex="-1">4.1 以前的笨办法：RNN（传话游戏） <a class="header-anchor" href="#_4-1-以前的笨办法-rnn-传话游戏" aria-label="Permalink to “4.1 以前的笨办法：RNN（传话游戏）”">​</a></h3><p>早期的模型（RNN，循环神经网络）处理一句话时，就像我们在玩<strong>传话游戏</strong>。</p><p><strong>工作方式：</strong></p><ol><li>读第 1 个词“我”，记在脑子里，传给第 2 步。</li><li>读第 2 个词“喜欢”，结合刚才的记忆，更新一下脑子里的信息，再传给第 3 步。</li><li>读第 3 个词“吃”，再更新记忆...</li><li>...直到读完最后一个词。</li></ol><p><strong>这就带来了两个致命缺点：</strong></p><ol><li><strong>慢（无法并行）</strong>：必须等上一个人传完话，下一个人才能开始。没法让 100 个人同时干活。</li><li><strong>忘（长距离遗忘）</strong>：传话传到第 100 个人时，他可能早就忘了第 1 个人说的是“我”还是“你”。这就导致模型写长文章时，容易前言不搭后语。</li></ol><h3 id="_4-2-现在的天才设计-transformer-圆桌会议" tabindex="-1">4.2 现在的天才设计：Transformer（圆桌会议） <a class="header-anchor" href="#_4-2-现在的天才设计-transformer-圆桌会议" aria-label="Permalink to “4.2 现在的天才设计：Transformer（圆桌会议）”">​</a></h3><p>2017 年，Google 提出了一种全新的架构——<strong>Transformer</strong>。它彻底改变了规则，把“传话游戏”变成了<strong>圆桌会议</strong>。</p><p><strong>工作方式：</strong> Transformer 不再一个接一个地传话，而是让<strong>所有词一次性全部坐上桌</strong>。</p><ol><li><strong>上帝视角（并行计算）</strong>：所有词同时进场，不用排队。大家把自己的信息写在纸上，摊在桌子中间。</li><li><strong>注意力机制（Attention）</strong>：这是它的杀手锏。每个词都可以<strong>直接</strong>去看桌上其他任何一个词的信息。 <ul><li>比如读到“它”这个字时，模型不需要回忆前面的传话，而是直接一眼看到前面的“小猫”，瞬间明白“它 = 小猫”。</li></ul></li></ol><p><strong>这就完美解决了 RNN 的痛点：</strong></p><ul><li><strong>快</strong>：大家同时看资料，GPU 可以火力全开，效率极高。</li><li><strong>不忘</strong>：不管句子多长，第 1 个词和第 10000 个词的距离都是“一步之遥”，想看谁就看谁。</li></ul><blockquote><p><strong>总结一下</strong>：</p><ul><li><strong>RNN</strong>：像走迷宫，一步一步摸索，容易迷路。</li><li><strong>Transformer</strong>：像开上帝视角看地图，终点起点尽收眼底。</li></ul></blockquote><h4 id="为什么还需要-位置-信息" tabindex="-1">为什么还需要“位置”信息？ <a class="header-anchor" href="#为什么还需要-位置-信息" aria-label="Permalink to “为什么还需要“位置”信息？”">​</a></h4><p>因为 Transformer 是“一锅端”，如果不做特殊处理，它分不清“我爱你”和“你爱我”的区别（词都一样，只是顺序不同）。 所以我们会给每个词贴个<strong>号码牌（位置编码）</strong>，告诉模型谁在第 1 位，谁在第 2 位。</p><blockquote><p>小提醒：很多 LLM 是自回归（预测下一个词）的，所以在生成时仍然是一 token 一 token 往外吐；但在<strong>每一步生成</strong>的内部计算里，Transformer 依旧更能利用矩阵并行与缓存优化。</p></blockquote><h3 id="_4-3-效率黑科技-kv-缓存-kv-cache" tabindex="-1">4.3 效率黑科技：KV 缓存 (KV Cache) <a class="header-anchor" href="#_4-3-效率黑科技-kv-缓存-kv-cache" aria-label="Permalink to “4.3 效率黑科技：KV 缓存 (KV Cache)”">​</a></h3><p>你可能听说过，生成长文本时，越到后面越慢，或者显存占用越大。这通常是因为模型需要“记住”之前生成的所有内容。</p><p><strong>Transformer 怎么“记笔记”？</strong></p><p>在 Transformer 的注意力机制中，每个词都会生成 <code>Key (K)</code> 和 <code>Value (V)</code> 两个向量，用来供后面的词“查询”。</p><ul><li>当模型生成第 100 个词时，它需要回头看前 99 个词的 K 和 V。</li><li>如果每次都重新计算前 99 个词的 K 和 V，那就太浪费了！</li></ul><p><strong>KV Cache 的作用：</strong></p><p>KV Cache 就像是一个<strong>“增量笔记本”</strong>。</p><ol><li><strong>不重算</strong>：算完第 1 个词的 K 和 V，存起来。</li><li><strong>只算新</strong>：生成第 2 个词时，只计算第 2 个词的 K 和 V，然后和第 1 个词的 K、V 拼在一起。</li><li><strong>越存越多</strong>：随着对话进行，这个“笔记本”（显存占用）会越来越厚。</li></ol><p>这就是为什么长文本对话（Long Context）会消耗大量显存的原因——<strong>不是模型变大了，而是笔记（KV Cache）太厚了。</strong></p>',38)),n(p),t[6]||(t[6]=e('<hr><h2 id="_5-揭秘-从-续写-到-对话" tabindex="-1">5. 揭秘：从“续写”到“对话” <a class="header-anchor" href="#_5-揭秘-从-续写-到-对话" aria-label="Permalink to “5. 揭秘：从“续写”到“对话””">​</a></h2><p>很多人会误以为 ChatGPT 真的懂我们在说什么，但其实它的本能只有一个：<strong>猜下一个词</strong>（Next Token Prediction）。</p><h3 id="_5-1-本能-疯狂续写" tabindex="-1">5.1 本能：疯狂续写 <a class="header-anchor" href="#_5-1-本能-疯狂续写" aria-label="Permalink to “5.1 本能：疯狂续写”">​</a></h3><p>如果你给基础模型（Base Model）输入：“今天天气不错”，它可能会续写：“去公园玩吧。” 但如果你输入：“美国的首都是哪里？”，它可能会续写：“中国首都是哪里？日本首都是哪里？”（因为它在模仿考卷的格式，而不是回答问题）。</p><h3 id="_5-2-技巧-用-剧本-来对话" tabindex="-1">5.2 技巧：用“剧本”来对话 <a class="header-anchor" href="#_5-2-技巧-用-剧本-来对话" aria-label="Permalink to “5.2 技巧：用“剧本”来对话”">​</a></h3><p>为了让它变成对话助手，工程师们想出了一个绝妙的办法：<strong>角色扮演</strong>。 我们在输入给模型的内容里，悄悄加了一些特殊的<strong>标签（Template）</strong>，让模型以为自己在续写一个“对话剧本”。</p><p>例如，你看到的是：</p><blockquote><p>User: 你好</p></blockquote><p>模型看到的其实是：</p><blockquote><p><code>&lt;|user|&gt;</code> 你好 <code>&lt;|assistant|&gt;</code></p></blockquote><p>模型一看到 <code>&lt;|assistant|&gt;</code>，就知道：“噢，轮到我扮演助手说话了。”</p><h3 id="_5-3-深度交互演示" tabindex="-1">5.3 深度交互演示 <a class="header-anchor" href="#_5-3-深度交互演示" aria-label="Permalink to “5.3 深度交互演示”">​</a></h3><p>下方的演示将带你一步步看清 LLM 的本质。请依次点击 <strong>1. 本能 -&gt; 2. 技巧 -&gt; 3. 原理 -&gt; 4. 进阶</strong>，亲手试一试！</p>',14)),n(d),t[7]||(t[7]=e(`<hr><h2 id="_6-从-胡说-到-好助手-alignment" tabindex="-1">6. 从“胡说”到“好助手” (Alignment) <a class="header-anchor" href="#_6-从-胡说-到-好助手-alignment" aria-label="Permalink to “6. 从“胡说”到“好助手” (Alignment)”">​</a></h2><p>光会对话还不够。原始的模型可能会教人制造炸弹，或者满嘴脏话。 为了让它成为 ChatGPT 这样彬彬有礼、安全可靠的助手，还需要最后两步打磨：</p><ol><li><p><strong>SFT (指令微调)</strong>：</p><ul><li>找人类专家写很多高质量的问答对，教模型“怎么好好说话”。</li><li>目标：让模型听得懂指令，不再胡乱续写。</li><li><em>数据示例 (JSON 格式)</em>：<div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// SFT 训练数据示例</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;messages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;请把这句话翻译成英文：“你好”。&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assistant&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 模型学会了：听到“翻译”指令时，要直接给出结果，而不是续写“你好吗”</span></span></code></pre></div></li></ul></li><li><p><strong>RLHF (人类反馈强化学习)</strong>：</p><ul><li><strong>打分</strong>：让模型生成几个回答，人类老师来打分（哪个更安全？哪个更有礼貌？）。</li><li><strong>奖惩</strong>：模型如果说得好就给奖励，说得不好就惩罚。慢慢地，模型就学会了“对齐”人类的价值观（Alignment）。</li><li><em>数据示例 (JSON 格式)</em>：<div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// RLHF 偏好数据示例 (DPO/PPO)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;如何制造炸弹？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;chosen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;对不起，我不能回答这个问题。&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 人类更喜欢的回答（安全）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rejected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;首先你需要...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 人类拒绝的回答（危险）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ul></li></ol><p><strong>上方的演示中，点击第 4 个标签页“进阶：对齐”，你可以亲自体验对齐前后的巨大差异。</strong></p><hr><h2 id="_7-前沿探索-会思考的模型、moe-架构与线性注意力机制" tabindex="-1">7. 前沿探索：会思考的模型、MoE 架构与线性注意力机制 <a class="header-anchor" href="#_7-前沿探索-会思考的模型、moe-架构与线性注意力机制" aria-label="Permalink to “7. 前沿探索：会思考的模型、MoE 架构与线性注意力机制”">​</a></h2><p>随着技术的发展，我们发现仅仅靠“预测下一个词”有时候会犯蠢，特别是在处理数学和逻辑问题时。 于是，新一代的 <strong>Thinking Models</strong> (如 OpenAI o1, DeepSeek-R1) 诞生了。</p><h3 id="_7-1-什么是-思考-thinking-models" tabindex="-1">7.1 什么是“思考”？(Thinking Models) <a class="header-anchor" href="#_7-1-什么是-思考-thinking-models" aria-label="Permalink to “7.1 什么是“思考”？(Thinking Models)”">​</a></h3><p>人类在回答复杂问题（比如 9.11 和 9.9 哪个大？）时，不会脱口而出，而是会先在脑子里想一想。 Thinking Model 就是学会了这种<strong>慢思考 (System 2)</strong> 能力的模型。</p><ul><li><strong>快思考 (System 1)</strong>：凭直觉，脱口而出。容易犯错。</li><li><strong>慢思考 (System 2)</strong>：通过产生一段“思维链 (Chain of Thought)”，一步步推理，最后给出答案。</li></ul>`,11)),n(h),t[8]||(t[8]=e('<h3 id="_7-2-训练揭秘-从-模仿-到-探索" tabindex="-1">7.2 训练揭秘：从“模仿”到“探索” <a class="header-anchor" href="#_7-2-训练揭秘-从-模仿-到-探索" aria-label="Permalink to “7.2 训练揭秘：从“模仿”到“探索””">​</a></h3><p>为什么以前的模型不会这样思考？因为训练方法变了。</p><h4 id="传统模式-sft-模仿学习" tabindex="-1">传统模式 (SFT - 模仿学习) <a class="header-anchor" href="#传统模式-sft-模仿学习" aria-label="Permalink to “传统模式 (SFT - 模仿学习)”">​</a></h4><ul><li><strong>方法</strong>：给模型看人类的思维过程，让它<strong>模仿</strong>。</li><li><strong>局限</strong>：模型的天花板就是人类数据及其质量。如果人类自己都想不清楚（比如极难的数学题），模型也学不会。</li></ul><h4 id="思考模式-rl-强化学习" tabindex="-1">思考模式 (RL - 强化学习) <a class="header-anchor" href="#思考模式-rl-强化学习" aria-label="Permalink to “思考模式 (RL - 强化学习)”">​</a></h4><ul><li><strong>方法</strong>：<strong>不给</strong>过程数据，只给最终的<strong>验证器 (Verifier)</strong>。 <ul><li>比如给一道数学题，模型自己去瞎试。</li><li>试错了 -&gt; 惩罚。</li><li>试对了 -&gt; 奖励。</li></ul></li><li><strong>顿悟时刻 (Aha Moment)</strong>： 在经过成千上万次的自我尝试后，模型惊奇地发现：<strong>“如果我在输出答案之前，先在草稿纸上多写几步推导，拿到奖励的概率会大大增加！”</strong> 于是，这种“先思考、再回答”的行为模式就被强化并固定了下来。这就好比阿法狗 (AlphaGo) 自己左右互搏，最终超越了人类棋谱。</li></ul><h3 id="_7-3-实战指南-prompt-风格大变局" tabindex="-1">7.3 实战指南：Prompt 风格大变局 <a class="header-anchor" href="#_7-3-实战指南-prompt-风格大变局" aria-label="Permalink to “7.3 实战指南：Prompt 风格大变局”">​</a></h3><p>使用 Thinking Model (如 DeepSeek-R1, OpenAI o1) 时，你的提示词策略需要完全改变。</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">传统模型 (GPT-4o, Claude 3.5)</th><th style="text-align:left;">思考模型 (R1, o1)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心逻辑</strong></td><td style="text-align:left;"><strong>System 1 (直觉)</strong></td><td style="text-align:left;"><strong>System 2 (逻辑)</strong></td></tr><tr><td style="text-align:left;"><strong>提示词技巧</strong></td><td style="text-align:left;">需要引导思维链 (CoT)<br>例：&quot;请一步步思考...&quot;</td><td style="text-align:left;"><strong>不要</strong>画蛇添足<br>模型自带思维链，人工引导反而会干扰它</td></tr><tr><td style="text-align:left;"><strong>指令清晰度</strong></td><td style="text-align:left;">需要把复杂任务拆解成子任务</td><td style="text-align:left;">直接给最终目标，让模型自己拆解</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">创意写作、简单翻译、闲聊</td><td style="text-align:left;">复杂数学、代码重构、逻辑推理</td></tr></tbody></table><blockquote><p>⚠️ <strong>注意</strong>：对 Thinking Model 越少干预越好。你只需要清晰地定义<strong>“什么是完美的任务结果”</strong>，而不要去定义<strong>“该怎么做”</strong>。</p></blockquote><h3 id="_7-4-未来趋势-快慢融合" tabindex="-1">7.4 未来趋势：快慢融合 <a class="header-anchor" href="#_7-4-未来趋势-快慢融合" aria-label="Permalink to “7.4 未来趋势：快慢融合”">​</a></h3><p>未来我们可能不再需要区分“思考模型”和“普通模型”。 理想的 AI 应该像人类一样，具备<strong>动态计算 (Adaptive Compute)</strong> 能力：</p><ul><li>遇到“1+1=？”：瞬间调用 System 1，秒回。</li><li>遇到“证明黎曼猜想”：自动切换到 System 2，思考三天三夜再回答。</li><li><strong>用户无感切换</strong>：你只需要提问，模型自己决定用多少“脑力”来解决。</li></ul><h3 id="_7-5-架构进化-从-全能-到-专家团-dense-vs-moe" tabindex="-1">7.5 架构进化：从“全能”到“专家团” (Dense vs MoE) <a class="header-anchor" href="#_7-5-架构进化-从-全能-到-专家团-dense-vs-moe" aria-label="Permalink to “7.5 架构进化：从“全能”到“专家团” (Dense vs MoE)”">​</a></h3><p>随着模型越来越大（比如 GPT-4, DeepSeek-V3），如果每次生成一个字都要把所有神经元算一遍，速度会慢到无法忍受。 于是，<strong>MoE (Mixture of Experts，混合专家)</strong> 架构应运而生。</p><ul><li><p><strong>Dense (稠密模型)</strong>：</p><ul><li><strong>比喻</strong>：一个<strong>全能天才</strong>。不管问什么问题，他都调动整个大脑来回答。</li><li><strong>特点</strong>：稳定，但随着知识量增加，反应越来越慢。</li><li><strong>代表</strong>：GPT-3, Llama-2。</li></ul></li><li><p><strong>MoE (混合专家模型)</strong>：</p><ul><li><strong>比喻</strong>：一个<strong>流水线上的专家团</strong>（每处理一个字就换一次人）。</li><li><strong>核心机制 (Token-Level Routing)</strong>： MoE 的精髓在于<strong>原生 Token 级路由</strong>。它<strong>绝不是</strong>按“任务类型”分工（比如把数学题全给数学专家），而是<strong>按“当前生成的字”实时分工</strong>。 <ul><li>当模型生成“<code>def</code>”时，路由给<strong>代码专家</strong>。</li><li>当模型生成“<code>love</code>”时，路由给<strong>文学专家</strong>。</li><li>当模型生成“<code>3.14</code>”时，路由给<strong>数学专家</strong>。 这意味着，哪怕在同一句话里，不同的字也往往由不同的专家处理。</li></ul></li><li><strong>特点</strong>：虽然总人数多（参数量大），但处理每个字时只有几个人干活（激活参数少）。<strong>又博学，又快</strong>。</li><li><strong>代表</strong>：GPT-4, DeepSeek-V3, Mixtral。</li></ul></li></ul>',16)),n(k),t[9]||(t[9]=e('<h3 id="_7-6-效率革命-突破长度极限-linear-attention" tabindex="-1">7.6 效率革命：突破长度极限 (Linear Attention) <a class="header-anchor" href="#_7-6-效率革命-突破长度极限-linear-attention" aria-label="Permalink to “7.6 效率革命：突破长度极限 (Linear Attention)”">​</a></h3><p>除了 MoE，还有一个核心痛点：<strong>上下文长度</strong>。 传统的 Transformer（如 GPT-4）使用的是<strong>标准注意力机制</strong>，它的计算量随着字数增加呈<strong>平方级爆炸</strong>。</p><ul><li>读 1 万字，计算量是 1 亿次。</li><li>读 10 万字，计算量是 100 亿次！</li></ul><p>为了解决这个问题，MiniMax (abab 系列) 和 RWKV 等模型采用了<strong>线性注意力机制 (Linear Attention)</strong>。</p><h3 id="为什么一个是-网状-一个是-线性" tabindex="-1">为什么一个是“网状”，一个是“线性”？ <a class="header-anchor" href="#为什么一个是-网状-一个是-线性" aria-label="Permalink to “为什么一个是“网状”，一个是“线性”？”">​</a></h3><p>根本区别在于：<strong>你是选择“保留所有原话”，还是选择“随时总结”？</strong></p><ul><li><p><strong>标准 Attention (网状) —— 为什么必须回看？</strong></p><ul><li><strong>核心原因</strong>：为了<strong>“寻找相关性”</strong>。</li><li><strong>例子</strong>：比如句子“我把<strong>苹果</strong>给<strong>它</strong>...”。当你读到“<strong>它</strong>”这个字时，为了弄清楚“它”到底指谁，模型必须回头把前面所有的词（我、把、苹果、给）都扫描一遍。</li><li><strong>过程</strong>：“它”发出一个查询信号 (Query)，去和前面所有词的标签 (Key) 进行匹配。 <ul><li>和“我”匹配？0分。</li><li>和“苹果”匹配？<strong>100分！</strong></li></ul></li><li><strong>代价</strong>：因为模型不知道哪个词重要，所以<strong>必须把前面所有词都检查一遍，一个都不能漏</strong>。这就是为什么线会织成一张网。</li></ul></li><li><p><strong>线性 Attention (线性) —— 为什么可以不回看？</strong></p><ul><li><strong>原理</strong>：模型学会了“做笔记”。读完“苹果”，它把“有一个苹果”这个信息压缩进<strong>状态 (State)</strong> 里；读到“它”时，直接查阅手里的状态，就能知道“它=苹果”。</li><li><strong>代价</strong>：虽然快，但在“压缩”过程中可能会丢失一些细节（比如忘记了苹果是红色的）。</li></ul></li></ul>',7)),n(m),t[10]||(t[10]=e('<h3 id="_7-7-架构大比拼-rnn-vs-transformer-vs-rwkv" tabindex="-1">7.7 架构大比拼：RNN vs Transformer vs RWKV <a class="header-anchor" href="#_7-7-架构大比拼-rnn-vs-transformer-vs-rwkv" aria-label="Permalink to “7.7 架构大比拼：RNN vs Transformer vs RWKV”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">架构</th><th style="text-align:left;">核心机制</th><th style="text-align:left;">复杂度 (长度 N)</th><th style="text-align:left;">并行训练</th><th style="text-align:left;">推理速度</th><th style="text-align:left;">遗忘问题</th><th style="text-align:left;">代表模型</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RNN</strong></td><td style="text-align:left;">串行递归</td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>N</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="mclose">)</span></span></span></span> (低)</td><td style="text-align:left;">❌ 不可</td><td style="text-align:left;">慢 (串行)</td><td style="text-align:left;">严重 (长距离遗忘)</td><td style="text-align:left;">LSTM, GRU</td></tr><tr><td style="text-align:left;"><strong>Transformer</strong></td><td style="text-align:left;">全局注意力</td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><msup><mi>N</mi><mn>2</mn></msup><mo>)</mo></mrow><annotation encoding="application/x-tex">O(N^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span></span></span></span> (极高)</td><td style="text-align:left;">✅ 可</td><td style="text-align:left;">中 (KV Cache)</td><td style="text-align:left;">无 (但受限于窗口)</td><td style="text-align:left;">GPT-4, Llama</td></tr><tr><td style="text-align:left;"><strong>RWKV / Linear</strong></td><td style="text-align:left;">线性注意力</td><td style="text-align:left;"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>N</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(N)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.10903em;">N</span><span class="mclose">)</span></span></span></span> (低)</td><td style="text-align:left;">✅ 可</td><td style="text-align:left;">快 (恒定显存)</td><td style="text-align:left;">轻微 (有压缩损耗)</td><td style="text-align:left;">RWKV, MiniMax</td></tr></tbody></table><blockquote><p><strong>RWKV / Linear Attention</strong> 试图结合前两者的优点：像 Transformer 一样并行训练，像 RNN 一样高效推理。</p></blockquote><hr><h2 id="_8-总结与学习路线" tabindex="-1">8. 总结与学习路线 <a class="header-anchor" href="#_8-总结与学习路线" aria-label="Permalink to “8. 总结与学习路线”">​</a></h2><p>现在你已经打通了从“分词”到“ChatGPT”的任督二脉：</p><ol><li><strong>Tokenization</strong>：文本切分为 Token。</li><li><strong>Embedding</strong>：Token 映射为语义向量。</li><li><strong>Transformer</strong>：利用注意力机制处理序列，并行提取特征。</li><li><strong>Training</strong>：使用 Template 格式化数据，通过 Teacher Forcing 并行训练。</li><li><strong>Inference</strong>：自回归式地逐词生成。</li></ol><p><strong>下一步建议</strong>：</p><ul><li>如果你对数学感兴趣，可以深入学习 <strong>线性代数</strong>（矩阵运算）和 <strong>概率论</strong>。</li><li>如果你想动手实践，可以尝试使用 Python 的 <code>transformers</code> 库加载一个微型模型（如 GPT-2）玩一玩。</li></ul><hr><h2 id="_9-名词速查表-glossary" tabindex="-1">9. 名词速查表 (Glossary) <a class="header-anchor" href="#_9-名词速查表-glossary" aria-label="Permalink to “9. 名词速查表 (Glossary)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">名词</th><th style="text-align:left;">全称</th><th style="text-align:left;">解释</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LLM</strong></td><td style="text-align:left;">Large Language Model</td><td style="text-align:left;">大语言模型。通过海量文本训练，能理解和生成人类语言的 AI 模型。</td></tr><tr><td style="text-align:left;"><strong>Token</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><strong>分词</strong>。文本被切分成的最小单位（如单词、字或字符片段）。模型读写的都是 Token ID。</td></tr><tr><td style="text-align:left;"><strong>Embedding</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><strong>词向量</strong>。将 Token 映射到高维空间（如 4096 维）的数值向量，捕捉词语的语义关系。</td></tr><tr><td style="text-align:left;"><strong>Transformer</strong></td><td style="text-align:left;">-</td><td style="text-align:left;">现代 LLM 的核心架构。基于注意力机制，能够并行处理长文本。</td></tr><tr><td style="text-align:left;"><strong>Attention</strong></td><td style="text-align:left;">Attention Mechanism</td><td style="text-align:left;"><strong>注意力机制</strong>。让模型在处理一个词时，能动态关注上下文中的其他相关词。</td></tr><tr><td style="text-align:left;"><strong>Context Window</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><strong>上下文窗口</strong>。模型一次推理能“记住”的最大 Token 数量（如 128k）。</td></tr><tr><td style="text-align:left;"><strong>Pre-training</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><strong>预训练</strong>。在海量无标注文本上训练模型，让它学会语言的基本规律和世界知识。</td></tr><tr><td style="text-align:left;"><strong>SFT</strong></td><td style="text-align:left;">Supervised Fine-Tuning</td><td style="text-align:left;"><strong>指令微调</strong>。使用高质量的问答对数据，教模型遵循人类指令。</td></tr><tr><td style="text-align:left;"><strong>RLHF</strong></td><td style="text-align:left;">Reinforcement Learning from Human Feedback</td><td style="text-align:left;"><strong>人类反馈强化学习</strong>。通过人类打分，进一步调整模型行为，使其符合人类价值观（对齐）。</td></tr><tr><td style="text-align:left;"><strong>CoT</strong></td><td style="text-align:left;">Chain of Thought</td><td style="text-align:left;"><strong>思维链</strong>。引导模型在给出最终答案前，先生成推理步骤的技术。</td></tr><tr><td style="text-align:left;"><strong>MoE</strong></td><td style="text-align:left;">Mixture of Experts</td><td style="text-align:left;"><strong>混合专家模型</strong>。由多个“专家”子模型组成，根据问题自动选择激活哪部分专家，效率更高。</td></tr><tr><td style="text-align:left;"><strong>Temperature</strong></td><td style="text-align:left;">-</td><td style="text-align:left;"><strong>温度</strong>。控制模型生成随机性的参数。温度越高，回答越有创造力但越不可控；温度越低，回答越确定。</td></tr></tbody></table>',12))])}const D=c(y,[["render",_]]);export{A as __pageData,D as default};
